package Controllers; import Services.CartService; import java.io.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/ViewCartServlet") public class ViewCartServlet extends HttpServlet{private final CartService s=new CartService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("cart",s.cart(r.getSession()));r.setAttribute("total",s.total(r.getSession()));r.getRequestDispatcher("CartView.jsp").forward(r,p);}}
